import { loadCanonicalComponentContracts } from "./canonical-component-contracts.mjs";
import { createFrameworkGenerationModel } from "./framework-generation.mjs";

export const VUE_CATALOG_ARTIFACT_PATH =
  "packages/ui-vue/src/generated/catalog.generated.ts";
export const VUE_CATALOG_TASK = "MFD-1304";

const SPECIALIZED = new Set(["button", "dialog", "tabs", "text-input"]);
const GENERATED_HEADER = `/**
 * @generated by scripts/vue-catalog-generation.mjs
 * Source: docs/metadata/component-contracts.json
 * DO NOT EDIT. Regenerate with: npm run generate:framework-artifacts
 */`;

function compareText(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function assert(condition, message) {
  if (!condition) throw new Error(`Vue catalog generation: ${message}`);
}

export function createVueCatalogModel(generationModel) {
  const vue = generationModel.surfaces.vue.components;
  const nativeById = new Map(
    generationModel.surfaces.native.components.map((record) => [
      record.id,
      record,
    ]),
  );
  const components = vue
    .filter((record) => ["current", "target"].includes(record.status))
    .map((record) => {
      const native = nativeById.get(record.id);
      assert(record.export, `${record.id}: Vue mapping requires an export`);
      assert(
        native?.tag,
        `${record.id}: canonical Native mapping requires a tag`,
      );
      assert(
        record.package === "@vyrnforge/ui-vue",
        `${record.id}: unexpected Vue package`,
      );
      assert(
        record.adapter.canonicalRenderer === "@vyrnforge/ui-elements",
        `${record.id}: Vue facade must delegate rendering to ui-elements`,
      );
      assert(
        !record.id.includes("data-grid"),
        `${record.id}: data grid is not part of the base Vue catalog`,
      );
      return {
        id: record.id,
        exportName: record.export,
        tag: native.tag,
        specialized: SPECIALIZED.has(record.id),
      };
    })
    .sort((left, right) => compareText(left.id, right.id));

  assert(
    components.length === 59,
    `expected 59 supported non-grid contracts, received ${components.length}`,
  );
  assert(
    new Set(components.map((entry) => entry.id)).size === components.length,
    "duplicate canonical component ids",
  );
  assert(
    new Set(components.map((entry) => entry.exportName)).size ===
      components.length,
    "duplicate Vue exports",
  );
  return Object.freeze(components);
}

function genericExportLine(component) {
  if (component.specialized) return `export { ${component.exportName} };`;
  return `export const ${component.exportName} = createVyrnForgeVueFacade("${component.exportName}", "${component.tag}");`;
}

export function serializeVueCatalog(components) {
  const specializedImports = components
    .filter((entry) => entry.specialized)
    .map(
      (entry) =>
        `import { ${entry.exportName} } from "./${entry.exportName}.generated";`,
    )
    .join("\n");
  const exportLines = components.map(genericExportLine).join("\n");
  const registryLines = components
    .map((entry) => `  ${entry.exportName},`)
    .join("\n");

  return `${GENERATED_HEADER}
import { defineComponent, h, useAttrs } from "vue";
import type { Component, Slots, VNode } from "vue";
import type { VyrnForgePublicElementTagName } from "@vyrnforge/ui-elements";

${specializedImports}

function renderSlots(slots: Slots): VNode[] {
  const children: VNode[] = [];
  if (slots.default) children.push(...slots.default());
  for (const [name, slot] of Object.entries(slots)) {
    if (name === "default" || !slot) continue;
    children.push(h("span", { slot: name }, slot()));
  }
  return children;
}

function createVyrnForgeVueFacade(
  name: string,
  tag: VyrnForgePublicElementTagName,
): Component {
  return defineComponent({
    name,
    inheritAttrs: false,
    setup(_, { slots, expose }) {
      const attrs = useAttrs();
      let element: Element | null = null;
      expose({
        get element() {
          return element;
        },
      });
      return () =>
        h(
          tag,
          {
            ...attrs,
            ref: (value: unknown) => {
              element = value instanceof Element ? value : null;
            },
          },
          renderSlots(slots),
        );
    },
  });
}

${exportLines}

export const vyrnForgeVueGeneratedComponents = Object.freeze([
${registryLines}
] as readonly Component[]);
`;
}

export function buildVueCatalogArtifact({ root } = {}) {
  const contracts = loadCanonicalComponentContracts({ root });
  const model = createFrameworkGenerationModel(contracts);
  const components = createVueCatalogModel(model);
  return Object.freeze({
    path: VUE_CATALOG_ARTIFACT_PATH,
    sourceRecords: ["component:*", "framework:vue:*", "framework:native:*"],
    content: serializeVueCatalog(components),
    components,
  });
}
